const __pageData = JSON.parse('{"title":"Marco Rubio","description":"","frontmatter":{"title":"Marco Rubio","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["state-department","diplomacy","trump-administration","middle-east"],"sources":["raw/badlands-brief-07c.md","raw/badlands-brief-0a2.md","raw/badlands-brief-05f.md","raw/badlands-brief-165.md","raw/badlands-brief-174.md","raw/badlands-brief-245.md","raw/badlands-brief-1ce.md","raw/badlands-brief-095.md","raw/badlands-brief-2c0.md","raw/badlands-brief-1ae.md","raw/badlands-brief-4ec.md","raw/badlands-brief-509.md","raw/badlands-brief-414.md","raw/badlands-brief-52f.md","raw/badlands-brief-5ba.md","raw/badlands-brief-686.md","raw/badlands-brief-6f4.md","raw/badlands-brief-733.md","raw/badlands-brief-740.md","raw/badlands-brief-861.md","raw/badlands-brief-9ea.md","raw/badlands-brief-98d.md","raw/badlands-brief-a9f.md","raw/badlands-brief-bf7.md","raw/badlands-brief-b62.md","raw/badlands-brief-d17.md","raw/badlands-brief-c7b.md","raw/badlands-brief-dc6.md","raw/badlands-brief-e60.md","raw/badlands-brief-e3b.md","raw/badlands-news-brief-02a.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-066.md","raw/badlands-news-brief-079.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-1ba.md","raw/badlands-news-brief-1c8.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-22b.md","raw/badlands-news-brief-243.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-471.md","raw/badlands-news-brief-540.md","raw/badlands-news-brief-541.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-6af.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-899.md","raw/badlands-news-brief-8a9.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/marco-rubio.md","filePath":"entities/marco-rubio.md","lastUpdated":null}');
